        product = self.catalog.get(sku)
        return product.sku

    def on_hand(self, sku: str) -> int:
        """Units physically in the stockroom."""
        key = self._sku(sku)
        ledger = self.ledger
        return (
            ledger.total(key, MovementKind.RECEIVE)
            + ledger.total(key, MovementKind.ADJUST)
            - ledger.total(key, MovementKind.SHIP)
