def import_stocktake(store: "Store", path: str | Path) -> tuple[RowError, ...]:
    """Read a stocktake count from a CSV file and adjust on-hand inventory.

    A bad row is skipped and reported; the other rows still apply.
    A file that is empty, not UTF-8, malformed for the csv module, or lacks exactly
    the columns 'sku' and 'counted' raises CsvFormatError and changes nothing.
    """
    try:
        with open(path, newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            header = reader.fieldnames
            if header is None:
                raise CsvFormatError("the file is empty")
            if sorted(name.strip() for name in header) != sorted(STOCKTAKE_COLUMNS):
                raise CsvFormatError(f"expected columns {','.join(STOCKTAKE_COLUMNS)}")
            reader.fieldnames = [name.strip() for name in header]
            errors: list[RowError] = []
            adjustments: list[tuple[str, int]] = []
            seen: set[str] = set()
            for row in reader:
                line = reader.line_num
                try:
                    adj = _parse_stocktake_row(store, row, seen)
                except StockroomError as exc:
                    errors.append(RowError(line, str(exc)))
                else:
                    seen.add(adj[0])
                    if adj[1] != 0:
                        adjustments.append(adj)
    except UnicodeDecodeError:
        raise CsvFormatError("the file is not valid UTF-8") from None
    except csv.Error as exc:
        raise CsvFormatError(f"the file is not valid CSV: {exc}") from None

    for sku, delta in adjustments:
        store.adjust(sku, delta, "stocktake")

    return RowErrors(errors)


def _parse_stocktake_row(
    store: "Store", row: dict[str, str | None], seen: set[str]
) -> tuple[str, int]:
    if None in row:
        raise CatalogError("row has more fields than the header")
    if any(value is None for value in row.values()):
        raise CatalogError("row has fewer fields than the header")
    fields = {key: value or "" for key, value in row.items()}
    raw_sku = fields["sku"].strip()
    if raw_sku not in store.catalog:
        raise UnknownSku(f"no such SKU: {raw_sku}")
    sku = normalize_sku(raw_sku)
    if sku in seen:
        raise DuplicateSku(f"duplicate SKU: {sku} already counted")
    raw_count = fields["counted"].strip()
    try:
        count = int(raw_count)
    except ValueError:
        raise InvalidQuantity(f"count is not a whole number: {raw_count!r}")
    if count < 0:
        raise InvalidQuantity(f"count must be 0 or more: {count}")
    reserved = store.inventory.reserved(sku)
    if count < reserved:
        raise InsufficientStock(
            f"cannot adjust {sku} to {count}: {reserved} reserved"
        )
    delta = count - store.inventory.on_hand(sku)
    return (sku, delta)


